    92→public(package) fun exchange_rate<MarketType>(self: &Reserve<MarketType>): Decimal {
    93→    if (self.total_supply == 0) {
    94→        return float::from_quotient(1, 1)
    95→    };
    96→
    97→    let numerator = self.cash_plus_borrows_minus_reserves();
    98→    let denominator = float::from(self.total_supply);
    99→
   100→    numerator.div(denominator)
   101→}
