public struct MarketConfiguration has store, copy, drop {
    close_factor: Decimal,
    close_factor_bypass_min_value: u64,
}

/// Flash loan hot potato
public struct FlashLoan<phantom MarketType, phantom CoinType> {
    inner: ReserveFlashLoan<MarketType, CoinType>,
    fee: u64,
}

public fun loan_amount<MarketType, CoinType>(self: &FlashLoan<MarketType, CoinType>): u64 {
    self.inner.amount()
}

